    "name": "Mineral Bottom",
    "region": "utah",
    "categories": [
      "trail"
    ],
    "lat": 38.50936,
    "lng": -109.99692,
    "area": "North of Canyonlands, Green River side",
    "signature": "The switchbacks up from the Green River to the Island.",
    "summary": "Mineral Bottom Road climbs from the Green River bottom to the Island in the Sky, a series of switchbacks that is the north entrance to the White Rim. It is steep, narrow, and the usual way out if you drove the rim from Shafer and do not want to reverse it.",
    "why": "The back door of Canyonlands.",
    "highlights": [
      "The switchbacks",
      "The river bottom",
      "The link onto the White Rim"
    ],
    "best": "March–November, dry",
    "time": "17 miles · 1–2 hours for the grade",
    "difficulty": "High clearance. The shelf is the issue.",
    "elevation": "From the river bottom up to the mesa",
    "fee": "The road leaves public land and enters the park. Park rules and fees apply once you are in.",
    "access": "From UT-313, the Island road, or from the White Rim if you are already on it. Also reached via the Horsethief / Mineral road from the north.",
    "tips": [
      "Do not meet a trailer in a switchback. Somebody is backing up, and it might be you.",
      "It connects to the White Rim. Decide that before you drop in."
    ],
    "watch": "Exposure and a grade that looks mild from the top.",
    "pairWith": [
      "white-rim",
      "shafer",
      "canyonlands"
    ],
    "established": "Route line © OpenStreetMap contributors, simplified",
