    "id": "medano",
    "name": "Medano Pass",
    "region": "colorado",
    "categories": [
      "trail"
    ],
    "lat": 37.82859,
    "lng": -105.45035,
    "area": "Great Sand Dunes",
    "signature": "A primitive road through the dunes, with creek crossings.",
    "summary": "The Medano Pass Primitive Road leaves the Great Sand Dunes, fords Medano Creek several times, and climbs to Medano Pass in the Sangre de Cristo. It is a national park primitive road: high clearance, sandy, and closed when the creek or the snow says so.",
    "why": "The dunes, from inside the park instead of from the parking lot.",
    "highlights": [
      "The creek crossings",
      "The sand",
      "The pass into the national forest"
    ],
    "best": "Typically May–October, creek-dependent. Spring runoff closes the fords.",
    "time": "16 miles · Half a day to a full day",
    "difficulty": "High clearance required. 4x4 is often needed in the sand. Not a sedan. The park will say so and mean it.",
    "elevation": "From the dune floor up to the pass near 10,000 ft",
    "fee": "Great Sand Dunes entrance fee. No extra permit for the road. It closes seasonally.",
    "permit": "Check the park's primitive-road status. The crossings are mandatory. You cannot drive around them without leaving the road, which you will not.",
    "access": "From the main dunes road. The primitive road is signed.",
    "tips": [
      "Walk a crossing before you drive it.",
      "Air down for the sand only if you can air up at the end."
    ],
    "watch": "Water depth and soft sand. People get stuck in sight of the parking lot and twenty miles later.",
    "status": "Park road. Check if the primitive road is open.",
    "pairWith": [
      "sand-dunes",
      "garden-gods"
    ],
    "established": "Route line © OpenStreetMap contributors, simplified",
